public static String generateStatement(Invoice invoice, Map<String, Play> plays) {
    StringBuilder result = new StringBuilder("Statement for " + invoice.getCustomer() + "\n");

    double totalAmount = calculateTotalAmount(invoice, plays);
    int volumeCredits = calculateTotalVolumeCredits(invoice, plays);

    for (Performance perf : invoice.getPerformances()) {
        Play play = plays.get(perf.getPlayID());
        result.append(formatPerformanceResult(play, perf));
    }

    result.append(String.format("Amount owed is %s\n", formatCurrency(totalAmount)));
    result.append(String.format("You earned %d credits\n", volumeCredits));
    return result.toString();
}

private static double calculateTotalAmount(Invoice invoice, Map<String, Play> plays) {
    double totalAmount = 0;
    for (Performance perf : invoice.getPerformances()) {
        Play play = plays.get(perf.getPlayID());
        double thisAmount = calculatePlayAmount(play, perf);
        totalAmount += thisAmount;
    }
    return totalAmount;
}

private static int calculateTotalVolumeCredits(Invoice invoice, Map<String, Play> plays) {
    int volumeCredits = 0;
    for (Performance perf : invoice.getPerformances()) {
        Play play = plays.get(perf.getPlayID());
        volumeCredits += calculatePerformanceVolumeCredits(play, perf);
    }
    return volumeCredits;
}

private static double calculatePlayAmount(Play play, Performance perf) {
    double thisAmount = 0;
    switch (play.getType()) {
        case "tragedy":
            thisAmount = 40000;
            if (perf.getAudience() > 30) {
                thisAmount += 1000 * (perf.getAudience() - 30);
            }
            break;
        case "comedy":
            thisAmount = 30000;
            if (perf.getAudience() > 20) {
                thisAmount += 10000 + 500 * (perf.getAudience() - 20);
            }
            thisAmount += 300 * perf.getAudience();
            break;
        default:
            throw new IllegalArgumentException("Unknown type: " + play.getType());
    }
    return thisAmount;
}

private static int calculatePerformanceVolumeCredits(Play play, Performance perf) {
    int volumeCredits = 0;
    volumeCredits += Math.max(perf.getAudience() - 30, 0);
    if ("comedy".equals(play.getType())) {
        volumeCredits += Math.floor(perf.getAudience() / 5);
    }
    return volumeCredits;
}

private static String formatPerformanceResult(Play play, Performance perf) {
    NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(Locale.US);
    double thisAmount = calculatePlayAmount(play, perf);
    return String.format(" %s: %s (%d seats)\n",
            play.getName(), currencyFormat.format(thisAmount / 100), perf.getAudience());
}

private static String formatCurrency(double amount) {
    NumberFormat currencyFormat = NumberFormat.getCurrencyInstance(Locale.US);
    return currencyFormat.format(amount / 100);
}
